import React, { useState, useEffect } from "react"
import "./Navbar.scss"
import logoV3 from "../images/logo-v3.png"

const Navbar = ({ onOpenModal }) => {
  const [scrolled, setScrolled] = useState(false)
  const [mobileOpen, setMobileOpen] = useState(false)

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 10)
    window.addEventListener("scroll", handleScroll)
    return () => window.removeEventListener("scroll", handleScroll)
  }, [])

  return (
    <nav
      className={`navbar ${scrolled ? "navbar--scrolled" : ""}`}
      role="navigation"
      aria-label="Primary navigation"
    >
      <div className="navbar__inner">
        <a href="/" className="navbar__logo">
          <img src={logoV3} alt="Staffy Health + Hospitality — Made in Canada" className="navbar__logo-img" />
        </a>

        <button
          type="button"
          className={`navbar__hamburger ${mobileOpen ? "active" : ""}`}
          onClick={() => setMobileOpen(!mobileOpen)}
          aria-label="Toggle menu"
          aria-expanded={mobileOpen}
          aria-controls="navbar-menu"
        >
          <span /><span /><span />
        </button>

        <div id="navbar-menu" className={`navbar__menu ${mobileOpen ? "navbar__menu--open" : ""}`}>
          <ul className="navbar__links">
            <li><a href="#solution" onClick={() => setMobileOpen(false)}>Solutions <svg width="10" height="6" viewBox="0 0 10 6" fill="none" aria-hidden="true"><path d="M1 1L5 5L9 1" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/></svg></a></li>
            <li><a href="#features" onClick={() => setMobileOpen(false)}>Industries <svg width="10" height="6" viewBox="0 0 10 6" fill="none" aria-hidden="true"><path d="M1 1L5 5L9 1" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/></svg></a></li>
            <li><a href="#use-case" onClick={() => setMobileOpen(false)}>Jobs <svg width="10" height="6" viewBox="0 0 10 6" fill="none" aria-hidden="true"><path d="M1 1L5 5L9 1" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/></svg></a></li>
            <li><a href="#difference" onClick={() => setMobileOpen(false)}>About</a></li>
          </ul>
          <div className="navbar__actions">
            <a href="#pilot" className="navbar__link-cta" onClick={() => setMobileOpen(false)}>
              Partner Login / Signup
            </a>
            <button
              type="button"
              className="btn btn--orange navbar__btn"
              onClick={() => { onOpenModal(); setMobileOpen(false) }}
            >
              Book a demo<br />(Facilities)
            </button>
            <a href="#pilot" className="btn btn--dark navbar__btn" onClick={() => setMobileOpen(false)}>
              Download the app<br />(Professionals)
            </a>
          </div>
        </div>
      </div>
    </nav>
  )
}

export default Navbar
